CREATE TABLE complaints (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), student_register TEXT NOT NULL, student_name TEXT, title TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'General', severity TEXT NOT NULL DEFAULT 'Medium', status TEXT NOT NULL DEFAULT 'Open', created_by TEXT NOT NULL, created_by_name TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now())